import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<List<String>> keranjang = Arrays.asList(
                Arrays.asList("kopi", "gula"),
                Arrays.asList("teh"),
                Arrays.asList("susu", "kopi", "roti"));

        List<String> semua = keranjang.stream()
                .flatMap(k -> k.stream())
                .collect(Collectors.toList());
        System.out.println(semua);
        System.out.println(semua.size());

        List<String> kalimat = Arrays.asList("belajar java", "java itu seru");
        List<String> kata = kalimat.stream()
                .flatMap(k -> Arrays.stream(k.split(" ")))
                .distinct()
                .collect(Collectors.toList());
        System.out.println(kata);
    }
}

