import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<List<String>> menuHarian = Arrays.asList(
                Arrays.asList("nasi", "ayam"),
                Arrays.asList("nasi", "ikan"),
                Arrays.asList("mie", "ayam"));
        List<String> semuaMenu = menuHarian.stream()
                .flatMap(m -> m.stream())
                .distinct()
                .sorted()
                .collect(Collectors.toList());
        System.out.println(semuaMenu);
    }
}

